/* Equipment catalog, inventory transactions, keyword effects and card picker. */
const EQ={query:'',kind:'all',tier:'all',magic:'all',book:'all',page:0,detail:null};
const eqItem=id=>EQ_CATALOG.find(x=>x.id===id);
const eqLabel=k=>({primary:'Primary weapon',secondary:'Secondary weapon',armor:'Armor',consumable:'Consumable',item:'Item'}[k]||k);
function eqEnsure(c){if(!c)return;c.items||=[];c.equipmentState||={effects:[],spent:{},reload:{}};c.equipmentState.effects||=[];c.equipmentState.spent||={};c.equipmentState.reload||={};c.equipmentState.ammo||={};if(!c.equipmentMigrated){for(const key of ['primary','secondary','armorId']){const id=c[key];if(eqItem(id)&&!c.items.some(x=>x.gear===id))c.items.push({uid:plId(),gear:id,qty:1,equipped:true});}const potion=EQ_CATALOG.find(x=>x.kind==='consumable'&&x.name===c.potion);if(potion)c.items.push({uid:plId(),gear:potion.id,qty:1});c.equipmentMigrated=true}if(!c.inventoryCardsMigrated){const lines=String(c.inventory||'').split('\n'),remaining=[];for(const line of lines){const e=EQ_CATALOG.find(e=>e.kind==='item'&&e.id.startsWith('supply-')&&e.name.toLowerCase()===line.trim().toLowerCase());if(e){if(!c.items.some(x=>x.gear===e.id))c.items.push({uid:plId(),gear:e.id,qty:1,equipped:false})}else remaining.push(line)}c.inventory=remaining.join('\n');c.inventoryCardsMigrated=true}}
function eqAdd(c,id,qty=1){eqEnsure(c);const e=eqItem(id);if(!e)throw Error('Oggetto non disponibile.');qty=Number(qty);if(!Number.isInteger(qty)||qty<1||qty>99)throw Error('Quantità non valida.');if(e.brawler)throw Error('Brawler’s Strike è una class feature.');const held=c.items.find(x=>x.gear===id);if((held?.qty||0)+qty>99)throw Error('Puoi portare al massimo 99 copie di un oggetto.');if(e.kind==='consumable'&&(held?.qty||0)+qty>5)throw Error('Puoi portare al massimo 5 copie di questo consumabile.');if(held)held.qty+=qty;else c.items.push({uid:plId(),gear:id,qty,equipped:false});plRecord(c,'Added '+qty+' × '+e.name)}
function eqEquipped(c){eqEnsure(c);return [...new Set([c.primary,c.secondary,c.armorId,...c.items.filter(x=>x.equipped&&eqItem(x.gear)?.kind==='item').map(x=>x.gear)])].map(eqItem).filter(Boolean)}
function eqLoadoutMax(c){return eqItem(c.armorId)?.feature.startsWith('Attuned:')?4:5}
function eqEquip(c,uid){eqEnsure(c);const held=c.items.find(x=>x.uid===uid),e=eqItem(held?.gear);if(!e)throw Error('Oggetto non trovato.');if(e.tier&&e.tier>plTier(c.level))throw Error('Questo equipaggiamento richiede Tier '+e.tier+'.');if(e.magic&&['primary','secondary'].includes(e.kind)&&!plSpell(c))throw Error('Le armi magiche richiedono un tratto Spellcast.');if(e.feature.startsWith('Pompous:')&&plStats(c).traits[4]>0)throw Error('Pompous richiede Presence 0 o inferiore.');if(e.kind==='consumable')throw Error('Usa il consumabile dall’inventario.');const key={primary:'primary',secondary:'secondary',armor:'armorId'}[e.kind];if(key){if(e.kind==='secondary'&&(plEquip(c.primary)?.hands!==1||plEquip(c.primary)?.brawler))throw Error('Serve una primaria a una mano per equipaggiare una secondaria.');if(e.feature.startsWith('Attuned:')&&plActive(c).length>4)throw Error('Sposta una carta nel Vault prima di equipaggiare Attuned (loadout massimo 4).');c.items.filter(x=>eqItem(x.gear)?.kind===e.kind).forEach(x=>x.equipped=false);c[key]=e.id;held.equipped=true;if(e.kind==='primary'&&(e.hands===2||e.brawler)){c.secondary='';c.items.filter(x=>eqItem(x.gear)?.kind==='secondary').forEach(x=>x.equipped=false)}}else{if(/Relic$/.test(e.name)&&c.items.some(x=>x.equipped&&x.uid!==uid&&/Relic$/.test(eqItem(x.gear)?.name)))throw Error('Puoi portare un solo relic: rimuovi prima quello attivo.');held.equipped=!held.equipped}plClampTracks(c);plRecord(c,'Equipped '+e.name)}
function eqUnequip(c,uid){const held=c.items.find(x=>x.uid===uid),e=eqItem(held?.gear);if(!held)return;held.equipped=false;if(c.primary===e.id){c.secondary='';c.items.filter(x=>eqItem(x.gear)?.kind==='secondary').forEach(x=>x.equipped=false)}for(const key of ['primary','secondary','armorId'])if(c[key]===e.id)c[key]='';plClampTracks(c)}
function eqRemove(c,uid,qty=1){const held=c.items.find(x=>x.uid===uid);if(!held||!Number.isInteger(qty)||qty<1||qty>held.qty)throw Error('Quantità non disponibile.');held.qty-=qty;if(!held.qty){eqUnequip(c,uid);c.items=c.items.filter(x=>x.uid!==uid)}}
function eqSell(c,uid,qty,price){if(!Number.isInteger(price)||price<0||price>99999)throw Error('Prezzo non valido.');const name=eqItem(c.items.find(x=>x.uid===uid)?.gear)?.name;eqRemove(c,uid,qty);c.gold+=price;plRecord(c,'Sold '+qty+' × '+name+' · '+price+' handfuls')}
function eqTransfer(c,recipient,uid,qty){if(!recipient||recipient.id===c.id)throw Error('Scegli un altro personaggio.');const held=c.items.find(x=>x.uid===uid);if(!held||!Number.isInteger(qty)||qty<1||qty>held.qty)throw Error('Quantità non disponibile.');eqAdd(recipient,held.gear,qty);eqRemove(c,uid,qty);plRecord(c,'Transferred '+qty+' × '+eqItem(held.gear).name+' to '+recipient.name)}
function eqApplyStats(c,st){
 eqEnsure(c);const equipped=eqEquipped(c);st.proficiency=c.proficiency;st.experiences=c.experiences.map(x=>({...x}));
 // Resolve trait modifiers first; armor may derive its score and thresholds from them.
 for(const e of equipped){const kw=e.feature.split(':')[0];if(kw==='Difficult'){st.evasion--;st.traits=st.traits.map(x=>x-1)}if(kw==='Cumbersome')st.traits[2]--;if(['Very Heavy','Destructive'].includes(kw))st.traits[0]--;if(kw==='Gilded')st.traits[4]++;if(/Relic$/.test(e.name)){const t=e.feature.match(/\+1 bonus to your (Agility|Strength|Finesse|Instinct|Presence|Knowledge)/);if(t)st.traits[PL_TRAITS.indexOf(t[1])]++}}
 for(const fx of c.equipmentState.effects){if(fx.trait!==undefined&&fx.expiry!=='next-roll')st.traits[fx.trait]+=fx.value;if(fx.evasion)st.evasion+=fx.evasion;if(fx.threshold){st.major+=fx.threshold;st.severe+=fx.threshold}if(fx.proficiency)st.proficiency+=fx.proficiency}
 for(const e of equipped){const f=e.feature||'',kw=f.split(':')[0],num=Number(f.match(/\+(\d+) to Armor Score/)?.[1]||0);if(['Protective','Barrier','Double Duty'].includes(kw))st.armor+=num;const ev=f.match(/([+−-]\d+) (?:to )?Evasion/);if(['Heavy','Very Heavy','Barrier','Massive','Brave','Bulky','Destructive','Flexible','Vigilant','Wall-Crawling'].includes(kw)&&ev)st.evasion+=Number(ev[1].replace('−','-'));if(kw==='Brave')st.severe+=3;if(kw==='Padded'){const n=Number(f.match(/\+(\d+)/)?.[1]||0);st.major+=n;st.severe+=n}if(kw==='Enchanted'){const n=st.traits[PL_TRAITS.indexOf(plSpell(c))]||0;st.major+=n;st.severe+=n}if(kw==='Magnificent')st.armor+=st.traits[4];if(kw==='Attuned'){st.major+=plTier(c.level);st.severe+=plTier(c.level)}}
 for(const e of equipped)if(e.name==='Honing Relic'){const held=c.items.find(x=>x.gear===e.id),xp=st.experiences[held?.experience??0];if(xp)xp.value++}st.armor=Math.max(0,st.armor);st.proficiency=Math.max(1,st.proficiency);
 for(const e of equipped){if(e.feature.startsWith('Reinforced:')&&st.armor>0&&c.armor>=st.armor){st.major+=2;st.severe+=2}if(e.feature.startsWith('Splintering:')){const n=Math.max(0,st.armor-c.armor);st.major+=n;st.severe+=n}}return st
}
function eqRollBonus(c,trait,type='action'){eqEnsure(c);let bonus=c.equipmentState.effects.filter(x=>x.expiry==='next-roll'&&x.trait===trait).reduce((n,x)=>n+x.value,0);const fx=plStats(c);bonus+=fx.rollBonus||0;if(type==='spellcast')bonus+=fx.spellBonus||0;if(type==='spellcast'&&eqEquipped(c).some(x=>x.feature.startsWith('Channeling:')))bonus++;return bonus}
function eqReset(c,when){eqEnsure(c);c.equipmentState.effects=c.equipmentState.effects.filter(x=>x.expiry!==when&&!(when==='long'&&x.expiry==='rest'));for(const key of Object.keys(c.equipmentState.spent))if(key.endsWith(':'+when)||when==='long'&&key.endsWith(':rest'))delete c.equipmentState.spent[key];if(['rest','long'].includes(when)){if(eqEquipped(c).some(x=>x.feature.startsWith('Self-Healing:')))c.armor=Math.max(0,c.armor-1);if(eqEquipped(c).some(x=>x.feature.startsWith('Healing:')))c.hp=Math.max(0,c.hp-1)}}
function eqPay(c,key,n){const max=key==='gold'?c.gold:key==='hope'?c.hope:plStats(c)[key]-c[key];if(n<0||n>max)throw Error('Non hai abbastanza '+key+'.');c[key]+=key==='hope'||key==='gold'?-n:n;if(key==='hope'&&n>0){const armor=eqItem(c.armorId);if(armor?.feature.startsWith('Resplendent:')&&!c.equipmentState.spent[armor.id+':scene']){c.armor=Math.max(0,c.armor-1);c.equipmentState.spent[armor.id+':scene']=true}}}
function eqUse(c,uid,choice='hp'){eqEnsure(c);const held=c.items.find(x=>x.uid===uid),e=eqItem(held?.gear);if(!e||e.kind!=='consumable'||!held.qty)throw Error('Consumabile non disponibile.');const f=e.feature;let result=e.name+': ',effects=[],heal=f.match(/^Clear (\d+)d(\d+)(?:\+(\d+))? (HP|Stress)\./i);if(heal){const n=Array.from({length:+heal[1]},()=>d(+heal[2])).reduce((a,b)=>a+b,0)+(+heal[3]||0),key=heal[4].toLowerCase()==='hp'?'hp':'stress';c[key]=Math.max(0,c[key]-n);result+='clear '+n+' '+heal[4]}else if(e.name==='Snap Powder'){eqPay(c,'stress',1);c.hp=Math.max(0,c.hp-1);result+='clear 1 HP'}else if(/clear all Hit Points and Stress/i.test(f)){c.hp=0;c.stress=0;result+='clear all HP and Stress'}else if(e.name==='Potion of Stability'){effects.push({downtime:1});result+='one additional downtime move'}else if(e.name==='Varik Leaves'){c.hope=Math.min(plStats(c).hope,c.hope+2);result+='+2 Hope'}else if(e.name==='Sweet Moss'){const n=d(4);c[choice]=Math.max(0,c[choice]-n);result+='clear '+n+' '+choice}else if(e.name==='Sun Tree Sap'){const n=d(6);if(n>=5)c.hp=Math.max(0,c.hp-2);else if(n>=2)c.stress=Math.max(0,c.stress-3);else c.conditions=[...(c.conditions||[]),'Sun Tree Sap: gain one scar'];result+='d6 '+n+' · '+(n>=5?'clear 2 HP':n>=2?'clear 3 Stress':'gain one scar')}else{const trait=f.match(/\+(\d+) bonus to your (?:next )?(Agility|Strength|Finesse|Instinct|Presence|Knowledge)/);if(trait)effects.push({trait:PL_TRAITS.indexOf(trait[2]),value:+trait[1]});if(e.name==='Shrinking Potion')effects.push({trait:0,value:2},{proficiency:-1});if(e.name==='Growing Potion')effects.push({trait:1,value:2},{proficiency:1});if(e.name==='Featherstep Potion')effects.push({evasion:plTier(c.level)});if(e.name==='Drakemantle')effects.push({threshold:5},{proficiency:1});if(e.name==='Lionheart Tonic')effects.push({proficiency:1});if(e.name==='Mirror of Marigold')eqPay(c,'hope',1);if(!effects.length)effects.push({text:f});result+=f}for(const fx of effects)c.equipmentState.effects.push({...fx,source:e.name,expiry:e.name==='Potion of Stability'?'rest':/next .*Roll/i.test(f)?'next-roll':/until.*(?:long rest)/i.test(f)?'long':/until.*rest/i.test(f)?'rest':/end of.*scene/i.test(f)?'scene':e.name==='Lionheart Tonic'?'fear':'manual'});eqRemove(c,uid);plRecord(c,result);EQ.result=result;plClampTracks(c);return result}
function eqDamage(c,damage,type,useArmor,mode='normal'){eqEnsure(c);const a=eqItem(c.armorId),f=a?.feature||'',st=plStats(c);if(type==='magic'&&f.startsWith('Warded:'))damage=Math.max(0,damage-st.armor);if(!damage)return 0;let hp=damage>=st.severe?3:damage>=st.major?2:1;if(mode==='lined'){if(!f.startsWith('Lined:')||hp!==1)throw Error('Lined si usa solo contro Minor damage.');eqPay(c,'stress',1);hp=0}else if(mode==='vitreous'){if(!f.startsWith('Vitreous:')||hp<3)throw Error('Vitreous richiede Severe damage.');eqPay(c,'armor',2);hp=0;c.equipmentState.effects.push({source:'Vitreous',threshold:-5,expiry:'manual'})}else if(useArmor){if(type==='physical'&&f.startsWith('Magic:')||type==='magic'&&f.startsWith('Physical:'))throw Error('Questa armatura non può ridurre questo tipo di danno.');if(c.armor>=st.armor)throw Error('Non hai slot Armor disponibili.');let mark=true;if(f.startsWith('Resilient:')&&c.armor===st.armor-1&&d(6)===6)mark=false;if(mark){c.armor++;if(f.startsWith('Painful:'))eqPay(c,'stress',1);if(f.startsWith('Divine:'))c.hope=Math.min(st.hope,c.hope+1)}hp=Math.max(0,hp-(f.startsWith('Fortified:')?2:1))}if(hp>=3&&f.startsWith('Bulky:'))eqPay(c,'stress',1);if(c.hp+hp>=st.hp&&mode==='impenetrable'){if(!f.startsWith('Impenetrable:')||c.equipmentState.spent[a.id+':rest'])throw Error('Impenetrable non disponibile.');eqPay(c,'stress',1);c.equipmentState.spent[a.id+':rest']=true;hp=Math.max(0,st.hp-c.hp-1)}c.hp=Math.min(st.hp,c.hp+hp);if(hp&&f.startsWith('Accursed:')&&d(4)===4)EQ.result='Accursed: attacker marks '+hp+' Stress';if(type==='magic'&&f.startsWith('Absorbing:')&&!c.equipmentState.spent[a.id+':scene']){c.armor=Math.max(0,c.armor-1);c.equipmentState.spent[a.id+':scene']=true}return hp}
function eqDamagePool(c,e,range,options={}){const st=plStats(c),prof=Math.max(1,(st.proficiency??c.proficiency)+(options.prof||0)),dice=[],formula=e.damage.replace(/phy|or|mag|\s|\//g,'');let flat=0;for(const m of formula.matchAll(/(\d*)d(\d+)|([+−-]\d+)/g)){if(m[2])for(let i=0;i<(+m[1]||1)*prof;i++)dice.push(options.devastating?20:+m[2]);else flat+=+m[3].replace('−','-')}const kw=e.feature.split(':')[0],rolls=dice.map(n=>d(n));if(['Powerful','Massive'].includes(kw)&&dice.length){rolls.push(d(dice[0]));rolls.splice(rolls.indexOf(Math.min(...rolls)),1)}for(let i=0;i<rolls.length;i++){if(kw==='Self-Correcting'&&rolls[i]===1)rolls[i]=6;if(kw==='Serrated'&&rolls[i]===1)rolls[i]=8;if(['Brutal','Recursive'].includes(kw)&&rolls[i]===dice[i]){let extra=d(dice[i]);rolls.push(extra);if(kw==='Recursive'){let guard=0;while(extra===dice[i]&&guard++<100){extra=d(dice[i]);rolls.push(extra)}}}}if(kw==='Bonded')flat+=c.level;if(kw==='Sharpwing')flat+=st.traits[0];if((kw==='Sharp'||eqItem(c.armorId)?.feature.startsWith('Sharp:'))&&range==='Melee')rolls.push(d(4));const secondary=eqItem(c.secondary);if(e.id===c.primary&&secondary){const f=secondary.feature;if(range==='Melee'&&/^Paired:|^Double Duty:/.test(f))flat+=f.includes('1 + your tier')?1+plTier(c.level):Number(f.match(/\+(\d+) to (?:primary weapon damage|Armor Score; \+\d+ to primary weapon damage)/)?.[1]||1);if(range==='Very Close'&&f.startsWith('Focused:'))flat++}flat+=(st.damageBonus||0)+(st.weaponDamage||0)+(range==='Melee'?st.meleeDamage||0:0);return {rolls,flat,maximum:dice.reduce((n,x)=>n+x,0),total:rolls.reduce((n,x)=>n+x,0)+flat}}
function eqWeaponFormula(c,e){if(!e)return '—';const st=plStats(c);let formula=e.damage.replace(/d/g,st.proficiency+'d'),bonus=0;if(e.feature.startsWith('Bonded:'))bonus+=c.level;if(e.feature.startsWith('Sharpwing:'))bonus+=st.traits[0];const secondary=eqItem(c.secondary);if(e.id===c.primary&&secondary){if(e.range==='Melee'&&/^Paired:|^Double Duty:/.test(secondary.feature))bonus+=secondary.feature.includes('1 + your tier')?1+plTier(c.level):Number(secondary.feature.match(/\+(\d+) to primary weapon damage/)?.[1]||1);if(e.range==='Very Close'&&secondary.feature.startsWith('Focused:'))bonus++}if(bonus)formula+=' '+sgn(bonus);return formula}
function eqAttack(c,id,options={}){let e=eqItem(id);if(!e||![c.primary,c.secondary].includes(id))throw Error('Equipaggia prima questa arma.');eqEnsure(c);if(options.versatile){const v=e.feature.match(/statistics[—–-](Agility|Strength|Finesse|Instinct|Presence|Knowledge), (Melee|Very Close|Close|Far|Very Far), (d\d+(?:\+\d+)?)(?: (phy|mag))?/);if(!v)throw Error('Modalità Versatile non disponibile.');e={...e,trait:v[1],range:v[2],damage:v[3]+' '+(v[4]|| (e.magic?'mag':'phy'))}}const distances=['Melee','Very Close','Close','Far','Very Far'],targetRange=options.range||e.range;if(distances.indexOf(targetRange)>distances.indexOf(e.range)&&!e.feature.startsWith('Omnipresent:'))throw Error('Il bersaglio è fuori portata.');if(e.feature.startsWith('Omnipresent:')&&targetRange==='Very Far')options.advantage='disadvantage';if(e.feature.startsWith('Aimed:')&&distances.indexOf(targetRange)<=1&&!options.ignoreAimed)options.advantage='disadvantage';if(options.ignoreAimed)eqPay(c,'stress',1);if(e.feature.startsWith('Six Shot:')){c.equipmentState.ammo[id]??=6;if(!c.equipmentState.ammo[id])throw Error('Non hai Ammo: ricarica segnando 1 Stress.');c.equipmentState.ammo[id]--}if(c.equipmentState.reload[id])throw Error('Arma da ricaricare: marca 1 Stress.');let st=plStats(c),trait=PL_TRAITS.indexOf(e.brawler?c.classChoices.strikeTrait||'Agility':e.trait),h=d(12),f=d(12),kw=e.feature.split(':')[0],bonus=eqRollBonus(c,trait,e.magic?'spellcast':'action');if(kw==='Reliable')bonus++;bonus+=st.attackBonus||0;if(e.id===c.primary&&eqItem(c.secondary)?.feature.startsWith('Trusty:'))bonus++;if(options.advantage)bonus+=d(6)*(options.advantage==='disadvantage'?-1:1);const total=h+f+st.traits[trait]+bonus,crit=h===f,success=crit||total>=options.difficulty,range=options.range||e.range;let prof=0;if(options.boost){eqPay(c,kw==='Greedy'?'gold':'stress',1);prof++}if(options.devastating)eqPay(c,'stress',1);let result=`${e.name} · Hope ${h} / Fear ${f} ${sgn(st.traits[trait]+bonus)} = ${total} · ${crit?'Critical':success?'Success':'Failure'}`;if(crit){c.hope=Math.min(st.hope,c.hope+(eqItem(c.secondary)?.feature.startsWith('Resonant:')?2:1));c.stress=Math.max(0,c.stress-1)}else if(h>f||kw==='Inverted')c.hope=Math.min(st.hope,c.hope+1);if(f>h)c.equipmentState.effects=c.equipmentState.effects.filter(x=>x.expiry!=='fear');c.equipmentState.effects=c.equipmentState.effects.filter(x=>!(x.expiry==='next-roll'&&x.trait===trait));if(success){if(options.followUp&&range==='Melee'&&e.id===c.primary&&eqItem(c.secondary)?.feature.startsWith('Follow-Up:')){eqPay(c,'stress',1);prof++}const pool=eqDamagePool(c,e,range,{prof,devastating:options.devastating});result+=` · Damage ${pool.total+(crit?pool.maximum:0)}${crit?' (critical +'+pool.maximum+')':''} [${pool.rolls.join(', ')}]${pool.flat?' '+sgn(pool.flat):''}`;if(kw==='Painful')eqPay(c,'stress',1);if(kw==='Invigorating'&&d(4)===4)c.stress=Math.max(0,c.stress-1);if((kw==='Bloodthirsty'||eqItem(c.armorId)?.feature.startsWith('Bloodthirsty:'))&&crit&&range==='Melee')c.hp=Math.max(0,c.hp-1);if(kw==='Lifestealing'&&d(6)===6)c[options.heal||'hp']=Math.max(0,c[options.heal||'hp']-1);if(kw==='Burning'&&pool.rolls.includes(6)||kw==='Scary')result+=' · Target marks 1 Stress';if(kw==='Piercing')result+=' · Target Major threshold −2';if(kw==='Nonlethal')result+=' · Target marks Stress instead of HP';if(kw==='Locked On')c.equipmentState.effects.push({source:e.name,text:'Next primary attack against this same target automatically succeeds.',expiry:'manual'});if(['Deadly','Venomous','Incendiary','Freezing','Disturbing','Bolstering','Eruptive','Long'].includes(kw))result+=' · '+e.feature}if(kw==='Reloading'&&d(6)===1){c.equipmentState.reload[id]=true;result+=' · Reload required'}EQ.result=result;PL.lastRoll=result;plRecord(c,result);plClampTracks(c);return result}
function eqBtn(action,label,attrs='',cls=''){return `<button type="button" class="btn ${cls}" data-eq="${action}" ${attrs}>${label}</button>`}
function eqArtSource(e){return typeof EQ_ART!=='undefined'?EQ_ART[e.id]||'':''}
function eqArtHTML(e,cls='eq-art'){const src=eqArtSource(e);return `<span class="${cls}" aria-hidden="true">${src?`<img src="${esc(src)}" alt="" loading="lazy" decoding="async">`:''}</span>`}
function eqFeatureHTML(feature){return String(feature||'').split('\n').map(line=>{const match=line.match(/^([^:]{1,65}):\s*(.*)$/);return match?`<strong class="eq-keyword">${esc(match[1])}:</strong> ${esc(match[2])}`:esc(line)}).join('<br>')}
// icone per tratto, range e danno nelle statistiche della carta
const EQ_ICO={trait:'<svg class="eq-ico" viewBox="0 0 16 16" aria-hidden="true"><path d="M8 1.5 13.5 3.6v4.1c0 3.3-2.3 5.9-5.5 6.8-3.2-.9-5.5-3.5-5.5-6.8V3.6z" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round"/><path d="M8 4.6 9 7l2.4.2-1.8 1.6.6 2.4L8 9.9l-2.2 1.3.6-2.4-1.8-1.6L7 7z" fill="currentColor"/></svg>',range:'<svg class="eq-ico" viewBox="0 0 16 16" aria-hidden="true"><circle cx="8" cy="8" r="6" fill="none" stroke="currentColor" stroke-width="1.4"/><circle cx="8" cy="8" r="3.2" fill="none" stroke="currentColor" stroke-width="1.4"/><circle cx="8" cy="8" r="1.1" fill="currentColor"/></svg>',damage:'<svg class="eq-ico" viewBox="0 0 16 16" aria-hidden="true"><path d="M8 .8l1.6 4.1 4.2-1.3-2.2 3.9 3.6 2.3-4.3.6.3 4.4L8 11.6l-3.2 3.2.3-4.4-4.3-.6 3.6-2.3L2.2 3.6l4.2 1.3z" fill="currentColor"/></svg>'};
function eqCard(e,mode='gallery'){const color={primary:'#926475',secondary:'#ae8443',armor:'#448b89',consumable:'#7963a3',item:'#657d8b'}[e.kind];return `<article class="eq-card" data-pl-card="${e.id}" style="--dc:${color}"><button type="button" class="kcard in still" data-eq="detail" data-id="${e.id}" aria-label="${esc(e.name)}"><span class="cd-i eq-face">${eqArtHTML(e)}<span class="eq-card-badges">${e.tier?`<span>Tier ${e.tier}</span>`:`<span>${e.rarity||'Item'}</span>`}${e.magic?'<span>Magic</span>':''}</span><span class="eq-card-content"><small>${eqLabel(e.kind)}</small><b>${esc(e.name)}</b><span class="eq-card-stats">${e.kind==='armor'?`${e.major}/${e.severe} · Armor ${e.score}`:e.damage?`${EQ_ICO.trait}<strong>${esc(e.trait)}</strong> · ${EQ_ICO.range}${esc(e.range)}<br>${EQ_ICO.damage}<strong>${esc(e.damage)}</strong> · ${e.hands} hand${e.hands>1?'s':''}`:e.kind==='consumable'?'Single use · Max 5':'Inventory item'}</span><span class="eq-feature">${eqFeatureHTML(e.feature)}</span></span><span class="cd-glare"></span></span><span class="cd-cap"><b>${esc(e.name)}</b><small>${e.book==='hf'?'Hope & Fear':'Core Rulebook'} · p.${e.page}</small></span></button>${mode==='picker'?`<div class="eq-card-actions">${eqBtn('add','＋ Aggiungi',`data-id="${e.id}"`,'pri')}${['primary','secondary','armor'].includes(e.kind)?eqBtn('add-equip','Aggiungi & equipaggia',`data-id="${e.id}"`):''}</div>`:''}</article>`}
function eqFiltered(picker=false){const c=picker?eqTarget():null;return EQ_CATALOG.filter(e=>!e.brawler&&(!EQ.query||(e.name+' '+e.feature).toLowerCase().includes(EQ.query.toLowerCase()))&&(EQ.kind==='all'||e.kind===EQ.kind||EQ.kind==='weapons'&&['primary','secondary'].includes(e.kind))&&(EQ.tier==='all'||String(e.tier)===EQ.tier)&&(EQ.magic==='all'||e.magic===(EQ.magic==='yes'))&&(EQ.book==='all'||e.book===EQ.book)&&(!picker||!EQ.start||((!e.campaign&&e.tier===1)||e.name==='Minor Health Potion'||e.name==='Minor Stamina Potion'))&&(!picker||!e.tier||e.tier<=plTier(c.level)))}
function eqFilterHTML(){return `<div class="eq-search"><input data-eq-filter="query" aria-label="Cerca equipaggiamento" placeholder="Search name or keyword…" value="${esc(EQ.query)}"><select data-eq-filter="book" aria-label="Equipment book">${[['all','Both manuals'],['core','Core Rulebook'],['hf','Hope & Fear']].map(([v,l])=>`<option value="${v}" ${EQ.book===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="eq-filters" aria-label="Equipment filters">${[['all','All'],['primary','Primary weapons'],['secondary','Secondary weapons'],['armor','Armor'],['consumable','Consumables'],['item','Items']].map(([v,l])=>eqBtn('filter',l,`data-field="kind" data-value="${v}" aria-pressed="${EQ.kind===v}"`,EQ.kind===v?'pri':'')).join('')}<span class="eq-filter-divider"></span>${[['all','Any tier'],['1','Tier 1'],['2','Tier 2'],['3','Tier 3'],['4','Tier 4']].map(([v,l])=>eqBtn('filter',l,`data-field="tier" data-value="${v}" aria-pressed="${EQ.tier===v}"`,EQ.tier===v?'pri':'')).join('')}${[['all','All damage types'],['yes','Magic'],['no','Physical / mundane']].map(([v,l])=>eqBtn('filter',l,`data-field="magic" data-value="${v}" aria-pressed="${EQ.magic===v}"`,EQ.magic===v?'pri':'')).join('')}</div>`}
function eqGridHTML(picker=false){const list=eqFiltered(picker),pages=Math.max(1,Math.ceil(list.length/24));EQ.page=Math.min(EQ.page,pages-1);return `${eqFilterHTML()}<div class="eq-result-count">${list.length} items${picker?' · Tier compatibili con il personaggio':''}</div><div class="cg eq-grid">${list.slice(EQ.page*24,EQ.page*24+24).map(e=>eqCard(e,picker?'picker':'gallery')).join('')||'<div class="pl-empty">Nessun oggetto con questi filtri.</div>'}</div><div class="pl-nav">${eqBtn('page','←',`data-delta="-1" ${EQ.page===0?'disabled':''}`)}<span>${EQ.page+1} / ${pages}</span>${eqBtn('page','→',`data-delta="1" ${EQ.page===pages-1?'disabled':''}`)}</div>`}
function renderEquipment(){return `<main class="pl eq-catalog"><header class="pl-head"><div><div class="pl-kicker">Core Rulebook + Hope & Fear</div><h1>Equipment</h1><p class="pl-note">Weapons, armor, items & consumables · ${EQ_CATALOG.filter(x=>!x.brawler).length} cards</p></div><div class="pl-actions"><button type="button" class="btn" data-eqp="open" title="Fogli A4 di mini card da ritagliare">🖨 Stampa carte${typeof EQP!=='undefined'&&EQP.sel.length?' ('+EQP.sel.reduce((n,x)=>n+x.n,0)+')':''}</button>${PL.chars.length?eqBtn('open-picker','＋ Add oggetto'):''}</div></header>${eqGridHTML()}${EQ.detail&&!PL.modal?eqDetailHTML(false):''}${plModal()}</main>`}
function eqTarget(){return EQ.draft?PL.draft:PL.chars.find(x=>x.id===EQ.character)||plCurrent()}
function eqPicker(c,kind='all',draft=false){if(!c)throw Error('Apri o crea prima un personaggio.');eqEnsure(c);EQ.character=c.id;EQ.draft=draft;EQ.start=draft;EQ.kind=kind;EQ.query='';EQ.book='all';EQ.tier='all';EQ.magic='all';EQ.page=0;EQ.detail=null;EQ.owned=null;EQ.inventorySlot=null;PL.modal={kind:'gear-picker'};PL.error='';EQ.message='';}
function eqPickerHTML(){const c=eqTarget();if(EQ.owned&&EQ.detail)return `<div class="eq-picker eq-owned-detail">${eqDetailHTML(true)}</div>`;return `<div class="eq-picker"><p class="pl-note">${esc(c.name||c.className)} · scegli le carte da aggiungere allo zaino. Puoi equipaggiare armi e armature direttamente.${EQ.start?' Starting equipment · Tier 1.':''}</p>${PL.error?`<p class="pl-error" role="alert">${esc(PL.error)}</p>`:''}${EQ.message?`<p class="eq-notice" role="status">${esc(EQ.message)}</p>`:''}${EQ.detail?eqDetailHTML(true):eqGridHTML(true)}</div>`}
function eqDetailHTML(inline){const e=eqItem(EQ.detail);if(!e)return '';const owned=inline&&eqTarget()?.items.find(x=>x.uid===EQ.owned&&x.gear===e.id);const body=`<div class="pl-head"><h2>${esc(e.name)}</h2>${owned?'':eqBtn('detail-close','← Indietro')}</div><div class="eq-detail">${owned?`<div class="eq-detail-card">${eqOwnedCard(eqTarget(),owned)}</div>`:eqArtHTML(e,'eq-detail-art')}<div><div class="pl-actions"><span class="pl-badge">${eqLabel(e.kind)}</span>${e.tier?`<span class="pl-badge">Tier ${e.tier}</span>`:''}${e.magic?'<span class="pl-badge">Magic</span>':''}<span class="pl-badge">${e.book==='hf'?'Hope & Fear':'Core Rulebook'} · p.${e.page}</span></div><h3>${e.kind==='armor'?`${e.major}/${e.severe} · Armor Score ${e.score}`:e.damage?`${esc(e.damage)} · ${e.hands} hand${e.hands>1?'s':''}`:e.rarity||'Item'}</h3>${e.trait?`<p>${esc(e.trait)} · ${esc(e.range)}</p>`:''}<p class="eq-feature-full">${eqFeatureHTML(e.feature)}</p>${e.campaign?`<p class="pl-note">Campaign: ${esc(e.campaign)}</p>`:''}${owned?'<p class="pl-note">Gestisci questo oggetto dai comandi sulla carta.</p>':inline?`<div class="pl-actions">${eqBtn('add','＋ Aggiungi',`data-id="${e.id}"`,'pri')}${['primary','secondary','armor'].includes(e.kind)?eqBtn('add-equip','Aggiungi & equipaggia',`data-id="${e.id}"`):''}</div>`:PL.chars.length?`<label>Personaggio<select id="eq-target">${PL.chars.map(c=>`<option value="${c.id}">${esc(c.name)} · Level ${c.level}</option>`).join('')}</select></label>${eqBtn('catalog-add','＋ Aggiungi allo zaino',`data-id="${e.id}"`,'pri')}`:'<p>Crea un personaggio per aggiungere questo oggetto.</p>'}</div></div>`;return inline?body:`<div class="pl-overlay"><section class="pl-dialog" role="dialog" aria-modal="true" aria-label="${esc(e.name)}">${body}</section></div>`}
function eqOwnedActions(c,x){const e=eqItem(x.gear),active=[c.primary,c.secondary,c.armorId].includes(e.id)||x.equipped;return `<div class="eq-owned-actions">${e.kind==='consumable'?eqBtn('use','Usa',`data-uid="${x.uid}"`):active?eqBtn('unequip','Rimuovi',`data-uid="${x.uid}"`):eqBtn('equip','Equipaggia',`data-uid="${x.uid}"`)}${e.damage&&active?eqBtn('attack','⚄ Attacca',`data-id="${e.id}" aria-label="Attack with ${esc(e.name)}" title="Tira attacco e danni"`,'primary eq-attack-btn'):''}${active&&c.equipmentState.reload[e.id]?eqBtn('reload','Reload',`data-id="${e.id}" title="Reload · 1 Stress"`):''}${active&&e.feature.startsWith('Six Shot:')?`<span class="eq-ammo-count">${c.equipmentState.ammo[e.id]??6}/6 Ammo</span>${eqBtn('ammo-reload','Reload',`data-id="${e.id}" title="Reload · 1 Stress"`)}`:''}${active&&e.feature!=='—'?eqBtn('keyword','✦',`data-id="${e.id}" aria-label="Keyword ${esc(e.name)}"`):''}${eqBtn('trade','⇄',`data-uid="${x.uid}" aria-label="Scambia ${esc(e.name)}"`)}${eqBtn('sell','Vendi',`data-uid="${x.uid}"`)}</div>`}
function eqOwnedCard(c,x){const e=eqItem(x.gear);if(!e)return '';let html=eqCard(e).replace(`data-eq="detail" data-id="${e.id}"`,`data-eq="inspect-owned" data-uid="${x.uid}" data-id="${e.id}"`).replace(`data-pl-card="${e.id}"`,`data-pl-card="owned-${x.uid}"`).replace('class="eq-card"',`class="eq-card eq-owned-card" ${['primary','secondary','armor'].includes(e.kind)?`draggable="true" data-eq-uid="${x.uid}"`:''}`);if(e.damage)html=html.replace(esc(e.damage),esc(eqWeaponFormula(c,e)));return html.replace('</article>',`<span class="eq-owned-quantity">×${x.qty}</span>${eqOwnedActions(c,x)}</article>`)}
function eqEmptySlot(label,action,attrs){return `<button type="button" class="eq-empty-slot" data-eq="${action}" ${attrs}><span>＋</span><b>${label}</b><small>Scegli una carta</small></button>`}
function eqEquippedCards(c){eqEnsure(c);return `<div class="eq-equipped-grid">${[['primary','Primary'],['secondary','Secondary'],['armorId','Armor']].map(([key,label])=>{const e=eqItem(c[key]),held=c.items.find(x=>x.gear===e?.id);return `<div class="eq-equipment-slot" data-eq-slot="${key}"><div class="eq-slot-heading"><b>${label}</b>${eqBtn('pick-slot','⇄',`data-kind="${key==='armorId'?'armor':key}" aria-label="Change ${label}"`)}</div>${held?eqOwnedCard(c,held):e?eqCard(e):eqEmptySlot(label,'pick-slot',`data-kind="${key==='armorId'?'armor':key}"`)}</div>`}).join('')}</div>`}
function eqInvSlots(c){const active=[c.primary,c.secondary],weapons=c.items.filter(x=>['primary','secondary'].includes(eqItem(x.gear)?.kind)&&!active.includes(x.gear));c.inventoryWeaponSlots||=[];const slots=c.inventoryWeaponSlots.slice(0,2).map(uid=>weapons.find(x=>x.uid===uid));for(let i=0;i<2;i++)if(!slots[i])slots[i]=weapons.find(x=>!slots.some(y=>y?.uid===x.uid));return {weapons,slots}}
function eqInventoryWeapons(c){const {weapons,slots}=eqInvSlots(c);return `<div class="eq-inventory-weapons">${[0,1].map(i=>`<div class="eq-equipment-slot" data-eq-slot="inv${i}"><div class="eq-slot-heading"><b>Inventory Weapon ${i+1}</b>${eqBtn('pick-inventory-weapon','⇄',`data-slot="${i}" aria-label="Choose Inventory Weapon ${i+1}"`)}</div>${slots[i]?eqOwnedCard(c,slots[i]):eqEmptySlot('Inventory Weapon '+(i+1),'pick-inventory-weapon',`data-slot="${i}"`)}</div>`).join('')}</div>${weapons.length>2?`<details class="eq-extra-weapons"><summary>Altre armi nello zaino (${weapons.length-2})</summary><div class="eq-mini-grid">${weapons.filter(x=>!slots.some(y=>y?.uid===x.uid)).map(x=>eqMiniCard(c,x)).join('')}</div></details>`:''}`}
function eqMiniCard(c,x){const e=eqItem(x.gear),active=!!x.equipped;return `<article class="eq-mini-card eq-kind-${e.kind}" data-pl-card="mini-${x.uid}" ${['primary','secondary','armor'].includes(e.kind)?`draggable="true" data-eq-uid="${x.uid}"`:''}><button type="button" class="eq-mini-open" data-eq="inspect-owned" data-uid="${x.uid}" aria-label="Open ${esc(e.name)}"><span class="eq-mini-art" aria-hidden="true"></span><span><small>${eqLabel(e.kind)}${active?' · Equipped':''}</small><b>${esc(e.name)}</b><em>×${x.qty}${e.tier?' · Tier '+e.tier:''}${e.magic?' · Magic':''}</em></span><i>↗</i></button>${eqOwnedActions(c,x)}${e.name==='Honing Relic'&&active?`<select aria-label="Honing Relic Experience" data-eq-experience="${x.uid}">${c.experiences.map((xp,i)=>`<option value="${i}" ${i===(x.experience??0)?'selected':''}>${esc(xp.name||'Experience '+(i+1))}</option>`).join('')}</select>`:''}</article>`}
function eqInventory(c){eqEnsure(c);const objects=c.items.filter(x=>['item','consumable'].includes(eqItem(x.gear)?.kind)),storedArmor=c.items.filter(x=>eqItem(x.gear)?.kind==='armor'&&x.gear!==c.armorId);return `<div class="eq-inventory eq-card-inventory"><div class="eq-inventory-head">${eqBtn('open-picker','＋ Add oggetto')}${eqBtn('trade-import','Importa scambio')}<input hidden id="eq-import" type="file" accept="application/json,.json"><span>${c.items.reduce((n,x)=>n+x.qty,0)} items</span></div>${eqInventoryWeapons(c)}<div class="eq-inventory-divider"><b>Items & consumables</b><span>Clicca per aprire la carta completa</span></div><div class="eq-mini-grid">${[...objects,...storedArmor].map(x=>eqMiniCard(c,x)).join('')||'<p class="pl-note">Nessun oggetto nello zaino.</p>'}</div>${c.outgoingTrades?.length?`<details class="eq-transfer-log"><summary>Scambi esportati</summary>${c.outgoingTrades.map((packet,i)=>`<div><span>${esc(eqItem(packet.gear)?.name)} ×${packet.qty}</span>${eqBtn('trade-download','Scarica',`data-index="${i}"`)}</div>`).join('')}</details>`:''}${c.equipmentState.effects.length?`<details><summary>Active item effects</summary>${c.equipmentState.effects.map((fx,i)=>`<div class="eq-inventory-row"><span>${esc(fx.source)} · ${esc(fx.text||[fx.trait!==undefined?sgn(fx.value)+' '+PL_TRAITS[fx.trait]:'',fx.evasion?sgn(fx.evasion)+' Evasion':'',fx.threshold?sgn(fx.threshold)+' thresholds':'',fx.proficiency?sgn(fx.proficiency)+' Proficiency':''].filter(Boolean).join(' · '))}<small>${fx.expiry}</small></span>${eqBtn('effect-end','Termina',`data-index="${i}"`)}</div>`).join('')}</details>`:''}</div>`}
function eqInventoryWeaponPicker(){const c=plCurrent(),list=c.items.filter(x=>['primary','secondary'].includes(eqItem(x.gear)?.kind)&&![c.primary,c.secondary].includes(x.gear));return `<p class="pl-note">Scegli un’arma che possiedi per questo slot. I suoi bonus si attivano solo quando la equipaggi.</p><div class="eq-mini-grid">${list.map(x=>`<button class="eq-choose-weapon" type="button" data-eq="assign-inventory-weapon" data-uid="${x.uid}" data-slot="${PL.modal.slot}"><b>${esc(eqItem(x.gear).name)}</b><small>${eqLabel(eqItem(x.gear).kind)} · Tier ${eqItem(x.gear).tier}</small></button>`).join('')||'<p>Non hai armi di riserva.</p>'}</div>${eqBtn('pick-weapons','＋ Aggiungi un’arma')}`}

function eqSlot(c,key){const e=eqItem(c[key]);return `<label>Name<div class="eq-slot-select">${eqBtn('pick-slot',esc(e?.name||'＋ Choose '+(key==='armorId'?'armor':key+' weapon')),`data-kind="${key==='armorId'?'armor':key}" aria-label="Choose ${key==='armorId'?'armor':key+' weapon'}${e?' · '+esc(e.name):''}"`)}${e?eqBtn('clear-slot','×',`data-key="${key}" aria-label="Unequip ${esc(e.name)}"`):''}</div></label>`}
function eqWeaponTools(c,key){const e=eqItem(c[key]);if(!e)return '';return `<div class="eq-weapon-tools">${eqBtn('attack','⚄ Attack',`data-id="${e.id}"`)}${e.feature.startsWith('Six Shot:')?`<span class="pl-badge">Ammo ${c.equipmentState.ammo[e.id]??6}/6</span>${eqBtn('ammo-reload','Reload · 1 Stress',`data-id="${e.id}"`)}`:''}${c.equipmentState?.reload[e.id]?eqBtn('reload','Reload · 1 Stress',`data-id="${e.id}"`):''}${e.feature!=='—'?eqBtn('keyword','Keyword',`data-id="${e.id}"`):''}</div>`}
function eqTransactionHTML(){const m=PL.modal,c=plCurrent(),held=c.items.find(x=>x.uid===m.uid),e=eqItem(held.gear);return `<p><b>${esc(e.name)}</b> · ${held.qty} disponibili</p><label>Quantità<input id="eq-quantity" type="number" min="1" max="${held.qty}" value="1"></label>${m.kind==='gear-sell'?`<label>Prezzo totale · handfuls of gold<input id="eq-price" type="number" min="0" value="0"></label><p class="pl-note">Inserisci il prezzo concordato con il GM.</p>${eqBtn('sell-confirm','Conferma vendita',`data-uid="${held.uid}"`,'pri')}`:`<label>Trasferisci a<select id="eq-recipient"><option value="">Scegli un personaggio…</option>${PL.chars.filter(x=>x.id!==c.id).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label><p class="pl-note">Trasferisce l’oggetto a un altro dei tuoi personaggi. Per scambiarlo con un altro giocatore usa il pacchetto di scambio: il destinatario può importarlo nella propria scheda.</p>${eqBtn('trade-confirm','Trasferisci',`data-uid="${held.uid}"`,'pri')}${eqBtn('trade-export','Esporta scambio',`data-uid="${held.uid}"`)}`}`}
function eqAttackHTML(){const e=eqItem(PL.modal.id);return `${e.feature.startsWith('Versatile:')?'<label class="pl-inline-check"><input id="eq-versatile" type="checkbox">Use alternative statistics (Versatile)</label>':''}${e.feature.startsWith('Aimed:')?'<label class="pl-inline-check"><input id="eq-ignore-aimed" type="checkbox">Ignore close-range disadvantage · 1 Stress</label>':''}<p>${eqFeatureHTML(e.feature)}</p><div class="pl-fields"><label>Target Difficulty<input id="eq-difficulty" type="number" min="1" max="99" value="12"></label><label>Target range<select id="eq-range">${['Melee','Very Close','Close','Far','Very Far'].map(x=>`<option ${x===e.range?'selected':''}>${x}</option>`).join('')}</select></label><label>Roll<select id="eq-advantage"><option value="">Normal</option><option value="advantage">Advantage</option><option value="disadvantage">Disadvantage</option></select></label></div>${/^Charged:|^Greedy:/.test(e.feature)?'<label class="pl-inline-check"><input id="eq-boost" type="checkbox"> +1 Proficiency · '+(e.feature.startsWith('Greedy:')?'1 Gold':'1 Stress')+'</label>':''}${e.feature.startsWith('Devastating:')?'<label class="pl-inline-check"><input id="eq-devastating" type="checkbox"> d20 damage dice · 1 Stress</label>':''}${eqItem(plCurrent()?.secondary)?.feature.startsWith('Follow-Up:')&&e.id===plCurrent().primary?'<label class="pl-inline-check"><input id="eq-follow-up" type="checkbox">Follow-Up on successful Melee attack · 1 Stress</label>':''}${eqBtn('attack-confirm','Tira attacco & danno',`data-id="${e.id}"`,'pri')}`}
function eqKeywordHTML(){const c=plCurrent(),e=eqItem(PL.modal.id),f=e.feature;return `<h3>${esc(f.split(':')[0])}</h3><p>${esc(f)}</p><p class="pl-note">I modificatori permanenti sono già inclusi nella scheda. Conferma solo quando si verifica il trigger della capacità; gli effetti su bersagli o alleati vengono registrati nel risultato per il tavolo.</p>${/mark.*Stress|spend.*Hope|mark.*Armor Slot|handful.*gold/i.test(f)?`<label>Risorse da spendere / segnare<input id="eq-cost" type="number" min="1" max="12" value="${/mark 2 Stress|mark 2 Armor/i.test(f)?2:1}"></label>${eqBtn('keyword-confirm','Attiva keyword',`data-id="${e.id}"`,'pri')}`:eqBtn('close','Chiudi')}`}
async function eqAction(action,o){const c=plCurrent();PL.error='';EQ.message='';switch(action){
case'nav-equipment':APP.sec='equipaggiamenti';PL.modal=null;render();return;case'nav-player':APP.sec='personaggi';PL.modal=null;render();return;
case'filter':EQ[o.field]=o.value;EQ.page=0;break;case'page':EQ.page=Math.max(0,EQ.page+Number(o.delta));break;case'detail':eqLbOpen(o.id,document.querySelector(`[data-eq="detail"][data-id="${CSS.escape(o.id)}"]`));return;case'detail-full':eqLbClose();EQ.detail=o.id;break;case'detail-close':EQ.detail=null;EQ.owned=null;break;
case'open-picker':{const target=c||PL.chars[0];eqPicker(target);break}case'pick-inventory-weapon':PL.modal={kind:'gear-inventory-weapon',slot:Number(o.slot)};break;case'assign-inventory-weapon':{const slots=c.inventoryWeaponSlots||=[];const other=1-Number(o.slot);if(slots[other]===o.uid)slots[other]=slots[Number(o.slot)]||null;slots[Number(o.slot)]=o.uid;plSave(c);PL.modal=null;break}case'pick-weapons':{const slot=PL.modal.slot;eqPicker(c);EQ.kind='weapons';EQ.inventorySlot=slot;break}
case'pick-slot':eqPicker(c,o.kind);break;case'pick-start':eqPicker(PL.draft,o.kind,true);break;
case'add':case'add-equip':{const target=eqTarget(),e=eqItem(o.id);const snapshot=plClone(target);if(EQ.start){target.items=target.items.filter(x=>eqItem(x.gear)?.kind!==e.kind);if(e.kind==='consumable')target.potion=e.name}eqAdd(target,e.id);if(action==='add-equip'||EQ.start&&['primary','secondary','armor'].includes(e.kind)){const held=target.items.find(x=>x.gear===e.id);try{eqEquip(target,held.uid)}catch(err){Object.assign(target,snapshot);throw err}}if(EQ.inventorySlot!==null&&EQ.inventorySlot!==undefined&&['primary','secondary'].includes(e.kind))(target.inventoryWeaponSlots||=[])[EQ.inventorySlot]=target.items.find(x=>x.gear===e.id).uid;EQ.message=e.name+' aggiunto'+(action==='add-equip'?' ed equipaggiato':' allo zaino');plSave(EQ.draft?null:target);break}
case'catalog-add':{const target=PL.chars.find(x=>x.id===document.getElementById('eq-target').value);eqAdd(target,o.id);plSave(target);toast(eqItem(o.id).name+' aggiunto allo zaino');break}
case'equip':eqEquip(c,o.uid);plSave(c);break;case'unequip':eqUnequip(c,o.uid);plSave(c);break;
case'clear-slot':{eqEnsure(c);const held=c.items.find(x=>x.gear===c[o.key]);if(held)eqUnequip(c,held.uid);else c[o.key]='';plSave(c);break}
case'inspect-owned':{const g=o.id||c.items.find(x=>x.uid===o.uid)?.gear;if(g){eqLbOpen(g,document.querySelector(`[data-eq="inspect-owned"][data-uid="${CSS.escape(o.uid)}"]`),o.uid);return}eqPicker(c);EQ.detail=c.items.find(x=>x.uid===o.uid).gear;EQ.owned=o.uid;break}case'inspect-owned-full':{eqLbClose();eqPicker(c);EQ.detail=c.items.find(x=>x.uid===o.uid).gear;EQ.owned=o.uid;break}
case'use':{const e=eqItem(c.items.find(x=>x.uid===o.uid)?.gear);if(!e)throw Error('Oggetto non trovato.');PL.modal={kind:'gear-use',uid:o.uid};break}
case'use-confirm':eqUse(c,o.uid,document.getElementById('eq-heal-choice')?.value||'hp');plSave(c);PL.modal=null;toast(EQ.result);break;
case'sell':case'trade':eqEnsure(c);PL.modal={kind:action==='sell'?'gear-sell':'gear-trade',uid:o.uid};break;
case'sell-confirm':{const qty=Number(document.getElementById('eq-quantity').value),price=Number(document.getElementById('eq-price').value);if(!Number.isInteger(qty)||!Number.isInteger(price)||price<0||price>99999)throw Error('Quantità o prezzo non valido.');eqSell(c,o.uid,qty,price);plSave(c);PL.modal=null;break}
case'trade-confirm':case'trade-export':{const qty=Number(document.getElementById('eq-quantity').value),held=c.items.find(x=>x.uid===o.uid);if(!Number.isInteger(qty)||qty<1||qty>held.qty)throw Error('Quantità non disponibile.');const e=eqItem(held.gear);if(action==='trade-confirm'){const recipient=PL.chars.find(x=>x.id===document.getElementById('eq-recipient').value&&x.id!==c.id);if(!recipient)throw Error('Scegli un altro personaggio.');eqTransfer(c,recipient,o.uid,qty);plSave(recipient)}else{const packet={type:'sablewood-equipment-trade',version:1,id:plId(),sender:c.name,gear:e.id,qty};plDownload(packet,'trade-'+e.id+'.json');eqRemove(c,o.uid,qty);(c.outgoingTrades||=[]).push(packet);plRecord(c,'Exported trade '+qty+' × '+e.name)}plSave(c);PL.modal=null;break}
case'trade-download':plDownload(c.outgoingTrades[Number(o.index)],'equipment-trade.json');return;
case'trade-import':document.getElementById('eq-import').click();return;
case'effect-end':eqEnsure(c);c.equipmentState.effects.splice(Number(o.index),1);plClampTracks(c);plSave(c);break;
case'attack':PL.modal={kind:'gear-attack',id:o.id};break;
case'attack-confirm':{const difficulty=Number(document.getElementById('eq-difficulty').value);if(!Number.isFinite(difficulty)||difficulty<1)throw Error('Difficulty non valida.');plFx(()=>{eqAttack(c,o.id,{difficulty,versatile:!!document.getElementById('eq-versatile')?.checked,ignoreAimed:!!document.getElementById('eq-ignore-aimed')?.checked,range:document.getElementById('eq-range').value,advantage:document.getElementById('eq-advantage').value,followUp:!!document.getElementById('eq-follow-up')?.checked,boost:!!document.getElementById('eq-boost')?.checked,devastating:!!document.getElementById('eq-devastating')?.checked});plSave(c);PL.modal=null});break}
case'ammo-reload':eqPay(c,'stress',1);c.equipmentState.ammo[o.id]=6;plSave(c);break;
case'reload':eqPay(c,'stress',1);c.equipmentState.reload[o.id]=false;plSave(c);break;
case'keyword':PL.modal={kind:'gear-keyword',id:o.id};break;
case'keyword-confirm':{const e=eqItem(o.id),f=e.feature,amount=Number(document.getElementById('eq-cost').value),period=/once per scene/i.test(f)?'scene':/once per long rest/i.test(f)?'long':/once per (short )?rest/i.test(f)?'rest':null;eqEnsure(c);if(!Number.isInteger(amount)||amount<1||amount>12)throw Error('Costo non valido.');if(period&&c.equipmentState.spent[e.id+':'+period])throw Error('Capacità già usata: '+period);const key=/mark.*Armor Slot/i.test(f)?'armor':/mark.*Stress/i.test(f)?'stress':/spend.*Hope/i.test(f)?'hope':'gold';eqPay(c,key,amount);if(period)c.equipmentState.spent[e.id+':'+period]=true;let effect='';if(f.startsWith('Timeslowing:'))effect='+'+d(4)+' Evasion against this attack';if(f.startsWith('Deflecting:'))effect='+'+plStats(c).armor+' Evasion against this attack';if(f.startsWith('Persuasive:'))c.equipmentState.effects.push({source:e.name,trait:4,value:2,expiry:'next-roll'});if(f.startsWith('Draining:'))c.stress=Math.max(0,c.stress-1);EQ.result=e.name+': '+(effect||f);PL.lastRoll=EQ.result;plRecord(c,EQ.result);plSave(c);PL.modal=null;break}
case'close':PL.modal=null;EQ.detail=null;break;
}eqRender()}
function eqRender(){if(APP.sec==='equipaggiamenti'&&!PL.modal){const root=document.querySelector('.eq-catalog');if(root){const t=document.createElement('template');t.innerHTML=renderEquipment();plMorph(root,t.content.firstElementChild);cardsObserve(root);return}}if(APP.sec==='equipaggiamenti'){render();return}plRender()}
let eqFilterTimer;
document.addEventListener('click',e=>{const b=e.target.closest('[data-eq]');if(!b||b.disabled)return;e.preventDefault();e.stopImmediatePropagation();Promise.resolve(eqAction(b.dataset.eq,b.dataset)).catch(err=>{PL.error=err.message;toast(err.message);eqRender()})},true);
document.addEventListener('change',async e=>{const el=e.target;if(el.dataset.eqExperience){const c=plCurrent(),held=c.items.find(x=>x.uid===el.dataset.eqExperience);held.experience=Number(el.value);plSave(c);eqRender();return}if(el.dataset.eqFilter){e.stopImmediatePropagation();EQ[el.dataset.eqFilter]=el.value;EQ.page=0;eqRender()}if(el.id==='eq-import'){try{const file=el.files?.[0];if(!file)return;if(file.size>100000)throw Error('File troppo grande.');const packet=JSON.parse(await file.text()),c=plCurrent();if(packet.type!=='sablewood-equipment-trade'||packet.version!==1||typeof packet.id!=='string'||!eqItem(packet.gear)||!Number.isInteger(packet.qty)||packet.qty<1||packet.qty>99)throw Error('Pacchetto di scambio non valido.');if(PL.chars.some(x=>x.receivedTrades?.includes(packet.id)))throw Error('Scambio già importato.');eqAdd(c,packet.gear,packet.qty);(c.receivedTrades||=[]).push(packet.id);plSave(c);toast('Oggetto ricevuto da '+packet.sender);eqRender()}catch(err){toast(err.message)}}},true);
document.addEventListener('input',e=>{if(e.target.dataset.eqFilter==='query'){e.stopImmediatePropagation();EQ.query=e.target.value;EQ.page=0;clearTimeout(eqFilterTimer);eqFilterTimer=setTimeout(eqRender,150)}},true);

// Apply equipment operations atomically: failed costs leave the character unchanged.
function eqAtomic(c,operation){const before=plClone(c);try{return operation()}catch(err){for(const key of Object.keys(c))delete c[key];Object.assign(c,before);throw err}}
const eqDamageOperation=eqDamage,eqAttackOperation=eqAttack,eqUseOperation=eqUse;
eqDamage=(c,...args)=>eqAtomic(c,()=>eqDamageOperation(c,...args));
eqAttack=(c,...args)=>eqAtomic(c,()=>eqAttackOperation(c,...args));
eqUse=(c,...args)=>eqAtomic(c,()=>eqUseOperation(c,...args));

document.addEventListener('keydown',e=>{if(EQ.detail&&!PL.modal&&e.key==='Escape'){e.preventDefault();EQ.detail=null;eqRender()}},true);

/* le carte equipaggiamento si ingrandiscono nello stesso visualizzatore delle carte dominio: carta a sinistra, dati a destra, frecce per scorrere */
const EQ_LB={list:[],uid:{}};
function eqLbOpen(id,src,uid){const box=src?.closest('.eq-catalog,.pl-official-panel,.pl-dialog,section,main')||document,els=[...box.querySelectorAll('[data-eq="detail"][data-id],[data-eq="inspect-owned"][data-id]')];EQ_LB.uid={};els.forEach(x=>{if(x.dataset.uid)EQ_LB.uid[x.dataset.id]=x.dataset.uid});if(uid)EQ_LB.uid[id]=uid;EQ_LB.ro=!!src?.closest('.tbl-sheet:not([data-own]),.gm-sheet-wrap');EQ_LB.list=[...new Set(els.map(x=>x.dataset.id))];if(!EQ_LB.list.includes(id))EQ_LB.list=[id];eqLbShow(id,'from',src)}
/* Carta equipaggiamento in formato stampa: mini card 41×63 mm (Mini American), testo grande e niente spazi vuoti.
   Le misure sono in mm così l'anteprima è proporzionata alla stampa; il testo dell'effetto si adatta allo spazio rimasto. */
/* Versione stampa = la stessa card della galleria, impaginata in 41×63 mm (mini card).
   La card si disegna a 289×444 px (proporzione 41:63) e si scala di 41mm/289px; il testo dell'effetto si adatta allo spazio. */
const EQ_PRINT_W=289,EQ_PRINT_H=Math.round(289*63/41);
function eqPrintCard(e){const book=e.book==='hf'?'Hope & Fear':e.book==='core'?'Core Rulebook':e.book?'Campagna':'';return `<div class="eq-print"><div class="eq-print-in pl" style="width:${EQ_PRINT_W}px;height:${EQ_PRINT_H}px">${eqCard(e,'view')}</div>${book?`<span class="eq-print-src">${esc(book)}${e.page?' · p. '+e.page:''}</span>`:''}</div>`}
function eqPrintFit(root){root.querySelectorAll('.eq-print-in').forEach(card=>{const c=card.querySelector('.eq-card-content'),f=card.querySelector('.eq-feature');if(!c||!f)return;const over=()=>c.scrollHeight>c.clientHeight+1;let px=15;f.style.fontSize=px+'px';while(over()&&px>8){px-=.5;f.style.fontSize=px+'px'}})}
function eqLbHTML(e){const pos=EQ_LB.list.indexOf(e.id),many=EQ_LB.list.length>1,color={primary:'#926475',secondary:'#ae8443',armor:'#448b89',consumable:'#7963a3',item:'#657d8b'}[e.kind]||'#657d8b';
 const pills=[e.tier?`Tier ${e.tier}`:(e.rarity||'Item'),e.trait,e.range,e.damage,e.hands?`${e.hands} hand${e.hands>1?'s':''}`:'',e.kind==='armor'?`Soglie ${e.major}/${e.severe}`:'',e.kind==='armor'?`Armor ${e.score}`:'',e.magic?'Magic':''].filter(Boolean).map((x,i)=>`<span ${i?'':'class="dm"'}>${esc(String(x))}</span>`).join('');
 const book=e.book==='hf'?'Hope & Fear':e.book==='core'?'Core Rulebook':'';
 return `<div class="lb-bd" data-a="cd-close"></div><button class="lb-x" data-a="cd-close" aria-label="Chiudi">×</button>
 ${many?`<button class="lb-nav prev" data-a="cd-nav" data-k="-1" aria-label="Precedente">‹</button><button class="lb-nav next" data-a="cd-nav" data-k="1" aria-label="Successiva">›</button>`:''}
 <div class="lb-body" style="--dc:${color}" role="document"><div class="lb-stage"><div class="lb-card"><div class="lb-f eq-lb-f"><div class="eq-lb-scale pl" inert>${eqPrintCard(e)}</div><span class="cd-glare"></span></div></div></div>
 <aside class="lb-info"><p class="lb-k">${esc(eqLabel(e.kind))}</p><h2 class="lb-t">${esc(e.name)}</h2><div class="lb-p">${pills}</div>
  ${e.feature&&e.feature!=='—'?`<p class="lb-f2 eq-lb-feat">${eqFeatureHTML(e.feature)}</p>`:''}${e.description?`<p class="lb-f2">${esc(e.description)}</p>`:''}
  ${book?`<p class="lb-f2">${book}${e.page?` · p. ${e.page}`:''}</p>`:''}
  <p>${EQ_LB.ro?'':EQ_LB.uid[e.id]?`<button class="btn" data-eq="inspect-owned-full" data-uid="${esc(EQ_LB.uid[e.id])}">Azioni sull'oggetto</button>`:`<button class="btn" data-eq="detail-full" data-id="${esc(e.id)}">Dettagli e azioni</button>`}</p>
  <p class="lb-f2 eq-lb-print">Anteprima di stampa · mini card 41 × 63 mm</p><p><button class="btn" data-eqp="add-only" data-id="${esc(e.id)}">＋ Aggiungi alla stampa</button> <button class="btn" data-eqp="open">Fogli di stampa</button></p><p class="lb-pos">${many?`${pos+1} di ${EQ_LB.list.length} · ← → per scorrere · `:''}Esc per chiudere</p></aside></div>`}
function eqLbFit(lb){const f=lb.querySelector('.eq-lb-f'),s=lb.querySelector('.eq-lb-scale');if(!f||!s)return;s.style.transform='none';eqPrintFit(s);const w=s.offsetWidth||300,h=s.offsetHeight||1,k=Math.min(f.clientWidth/w,f.clientHeight/h);s.style.transform=`translate(${(f.clientWidth-w*k)/2}px,${(f.clientHeight-h*k)/2}px) scale(${k})`}
function eqLbShow(id,how,src){const e=eqItem(id);if(!e)return;let lb=document.getElementById('cd-lb');
 if(!lb){lb=document.createElement('div');lb.id='cd-lb';lb.className='lb';lb.setAttribute('role','dialog');lb.setAttribute('aria-modal','true');lb.setAttribute('aria-label','Carta ingrandita');document.body.appendChild(lb);document.body.classList.add('lb-on')}
 CV.open='eq:'+id;lb.innerHTML=eqLbHTML(e);eqLbFit(lb);lb.querySelectorAll('img').forEach(i=>i.addEventListener('load',()=>eqLbFit(lb),{once:true}));
 const card=lb.querySelector('.lb-card');if(creduced()||!card?.animate)return;
 if(how==='next'||how==='prev'){const s=how==='next'?1:-1;card.animate([{opacity:0,transform:`translateX(${s*10}px)`},{opacity:1,transform:'none'}],{duration:180,easing:'ease-out'})}
 else card.animate([{opacity:0,transform:'scale(.97)'},{opacity:1,transform:'none'}],{duration:220,easing:'ease-out'})}
function eqLbNav(k){const id=String(CV.open).slice(3),j=EQ_LB.list.indexOf(id),n=EQ_LB.list[((j<0?0:j)+k+EQ_LB.list.length)%EQ_LB.list.length];if(n)eqLbShow(n,k>0?'next':'prev')}

function eqLbClose(){if(typeof document==='undefined')return;document.getElementById?.('cd-lb')?.remove();document.body?.classList?.remove('lb-on');if(typeof CV!=='undefined')CV.open=null}

/* Trascina le carte equipaggiamento: dall'inventario a uno slot attivo (e viceversa) si scambiano. */
function eqDrop(c,uid,slot){eqEnsure(c);const held=c.items.find(x=>x.uid===uid),e=eqItem(held?.gear);if(!e)return;
 const shown=eqInvSlots(c).slots.map(x=>x?.uid||''),fromInv=shown.indexOf(uid),act={primary:'primary',secondary:'secondary',armorId:'armor'};
 const commit=()=>{c.inventoryWeaponSlots=shown.slice(0,2)};
 if(act[slot]){if(e.kind!==act[slot])throw Error(`${e.name} non va nello slot ${slot==='armorId'?'Armor':slot==='primary'?'Primary':'Secondary'}.`);
  const prev=c.items.find(x=>x.gear===c[slot]&&x.equipped);if(prev?.uid===uid)return;eqEquip(c,uid);
  // l'arma tolta dallo slot attivo prende il posto di quella appena equipaggiata nell'inventario
  if(fromInv>=0){shown[fromInv]=prev&&['primary','secondary'].includes(eqItem(prev.gear)?.kind)?prev.uid:'';commit()}return}
 const i=+slot.slice(3);if(!['primary','secondary'].includes(e.kind))throw Error('Negli slot Inventory Weapon vanno solo armi.');
 const there=shown[i],thereItem=c.items.find(x=>x.uid===there);if(there===uid)return;
 if(held.equipped){eqUnequip(c,uid);shown[i]=uid;
  // scambio: se nello slot c'era un'arma dello stesso tipo, va nello slot attivo
  if(thereItem&&eqItem(thereItem.gear)?.kind===e.kind){try{eqEquip(c,thereItem.uid)}catch(err){shown[i]=uid}}}
 else{if(fromInv>=0)shown[fromInv]=there||'';shown[i]=uid}
 commit()}
let EQ_DRAG=null;
document.addEventListener('dragstart',e=>{const el=e.target.closest?.('[data-eq-uid]');if(!el)return;EQ_DRAG=el.dataset.eqUid;e.dataTransfer.effectAllowed='move';try{e.dataTransfer.setData('text/plain',EQ_DRAG)}catch(x){}document.body.classList.add('eq-dragging')});
document.addEventListener('dragend',()=>{EQ_DRAG=null;document.body.classList.remove('eq-dragging');document.querySelectorAll('.eq-drop-on').forEach(x=>x.classList.remove('eq-drop-on'))});
document.addEventListener('dragover',e=>{if(!EQ_DRAG)return;const s=e.target.closest?.('[data-eq-slot]');if(!s)return;e.preventDefault();e.dataTransfer.dropEffect='move';document.querySelectorAll('.eq-drop-on').forEach(x=>x!==s&&x.classList.remove('eq-drop-on'));s.classList.add('eq-drop-on')});
document.addEventListener('drop',e=>{if(!EQ_DRAG)return;const s=e.target.closest?.('[data-eq-slot]');if(!s)return;e.preventDefault();const c=plCurrent(),uid=EQ_DRAG;EQ_DRAG=null;document.body.classList.remove('eq-dragging');try{eqDrop(c,uid,s.dataset.eqSlot);plSave(c)}catch(err){toast(err.message)}plRender()});
